'use strict';

// MODULES //

var logger = require( 'debug' );
var remark = require( 'remark' );
var frontmatter = require( 'remark-frontmatter' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isBuffer = require( '@stdlib/assert/is-buffer' );
var fromString = require( '@stdlib/buffer/from-string' );
var objectKeys = require( '@stdlib/utils/keys' );
var objectAssign = require( '@stdlib/object/assign' );
var format = require( '@stdlib/string/format' );
var defaults = require( './defaults.json' );
var validate = require( './validate.js' );
var build = require( './build.js' );


// VARIABLES //

var debug = logger( 'markdown-to-semantic-document:main' );
var parser = remark().use( frontmatter );


// FUNCTIONS //

/**
* Returns conversion options.
*
* @private
* @param {Options} [options] - conversion options
* @returns {Options} conversion options
*/
function createOptions( options ) {
	var opts;
	var keys;
	var k;
	var i;

	// Copy defaults and user options into a fresh object. This prevents callers from observing mutation and ignores properties inherited through prototypes...
	debug( 'Creating conversion options...' );
	opts = objectAssign( {}, defaults );
	if ( arguments.length ) {
		keys = objectKeys( options );
		for ( i = 0; i < keys.length; i++ ) {
			k = keys[ i ];
			opts[ k ] = options[ k ];
		}
	}
	debug( 'Created conversion options: mode=%s profile=%s includePositions=%s includeSourceSlices=%s', opts.mode, opts.profile, opts.includePositions, opts.includeSourceSlices );
	return opts;
}

/**
* Tests whether two buffers contain the same bytes.
*
* @private
* @param {Buffer} x - first buffer
* @param {Buffer} y - second buffer
* @returns {boolean} boolean indicating whether buffers contain the same bytes
*/
function equalBytes( x, y ) {
	var i;

	// Length must be checked first; the loop then verifies every original byte...
	if ( x.length !== y.length ) {
		return false;
	}
	for ( i = 0; i < x.length; i++ ) {
		if ( x[ i ] !== y[ i ] ) {
			return false;
		}
	}
	return true;
}

/**
* Returns a Markdown string and the exact input bytes.
*
* @private
* @param {(string|Buffer)} markdown - input Markdown
* @throws {TypeError} Buffer must contain valid UTF-8
* @returns {Object} source data
*/
function source( markdown ) {
	var bytes;
	var str;

	debug( 'Normalizing Markdown input: type=%s', ( isString( markdown ) ) ? 'string' : 'buffer' );
	if ( isString( markdown ) ) {
		// For strings, UTF-8 encoding defines the byte representation used by the document digest and source metadata...
		str = markdown;
		bytes = fromString( str, 'utf8' );
		debug( 'Normalized Markdown input: characters=%d bytes=%d', str.length, bytes.length );
		return {
			'bytes': bytes,
			'value': str
		};
	}
	str = markdown.toString( 'utf8' );
	bytes = fromString( str, 'utf8' );

	// Node replaces malformed UTF-8 with replacement characters. A round trip is therefore required to reject invalid bytes rather than silently changing input...
	if ( !equalBytes( bytes, markdown ) ) {
		debug( 'Unable to normalize Markdown Buffer: invalid UTF-8.' );
		throw new TypeError( 'invalid argument. Buffer must contain valid UTF-8 encoded Markdown.' );
	}
	debug( 'Normalized Markdown input: characters=%d bytes=%d', str.length, bytes.length );
	return {
		'bytes': markdown,
		'value': str
	};
}

/**
* Tests whether a semantic document has fatal diagnostics.
*
* @private
* @param {Object} doc - semantic document
* @returns {boolean} boolean indicating whether a document has fatal diagnostics
*/
function hasErrors( doc ) {
	var i;

	// Warnings and informational diagnostics remain valid strict-mode output...
	for ( i = 0; i < doc.diagnostics.length; i++ ) {
		if ( doc.diagnostics[ i ].severity === 'error' ) {
			return true;
		}
	}
	return false;
}


// MAIN //

/**
* Converts Markdown to a semantic document.
*
* @param {(string|Buffer)} markdown - Markdown to convert
* @param {Options} [options] - conversion options
* @param {string} [options.mode='permissive'] - conversion mode
* @param {string} [options.profile='readme'] - semantic profile
* @param {boolean} [options.includePositions=true] - boolean indicating whether to include source positions
* @param {boolean} [options.includeSourceSlices=false] - boolean indicating whether to include source slices
* @throws {TypeError} first argument must be a string or Buffer
* @throws {TypeError} second argument must be a valid options object
* @throws {Error} strict conversion encountered an error diagnostic
* @returns {Object} semantic document
*
* @example
* var markdown = '# abs\n\n> Compute an absolute value.';
*
* var doc = convert( markdown );
* // returns {...}
*/
function convert( markdown, options ) {
	var input;
	var opts;
	var tree;
	var doc;
	var err;

	debug( 'Converting Markdown to a semantic document...' );

	// Validate the public boundary before invoking remark; parser errors should never stand in for clear argument or option errors...
	if ( !isString( markdown ) && !isBuffer( markdown ) ) {
		debug( 'Unable to convert Markdown: invalid input type.' );
		throw new TypeError( format( 'invalid argument. First argument must be either a string or a Buffer. Value: `%s`.', markdown ) );
	}
	if ( arguments.length > 1 ) {
		err = validate( options );
		if ( err ) {
			throw err;
		}
		opts = createOptions( options );
	} else {
		opts = createOptions();
	}
	input = source( markdown );
	debug( 'Normalized Markdown source: characters=%d bytes=%d', input.value.length, input.bytes.length );

	// Parsing and semantic construction are separate stages. The builder receives both decoded text and exact bytes because provenance and digest needs differ...
	debug( 'Parsing Markdown...' );
	tree = parser.parse( input.value );
	debug( 'Parsed Markdown: rootChildren=%d', tree.children.length );

	debug( 'Building semantic document...' );
	doc = build( tree, input.value, input.bytes, opts );
	debug( 'Built semantic document: children=%d diagnostics=%d accounting=%d', doc.children.length, doc.diagnostics.length, doc.accounting.length );

	// Strict mode is a policy over diagnostics, not an alternate conversion path. Attach the completed document so callers can inspect every discovered issue...
	if ( opts.mode === 'strict' && hasErrors( doc ) ) {
		debug( 'Unable to complete strict conversion: error diagnostics encountered.' );
		err = new Error( 'invalid argument. Unable to convert Markdown to a semantic document without errors.' );
		err.document = doc;
		throw err;
	}
	debug( 'Successfully converted Markdown to a semantic document.' );
	return doc;
}


// EXPORTS //

module.exports = convert;
